# ---------- 1. Clopper-Pearson 95% CI via regularized incomplete beta (continued fraction, pure python)
def log_gamma(x):
    # Lanczos approximation
    g=7; c=[0.99999999999980993,676.5203681218851,-1259.1392167224028,
           771.32342877765313,-176.61502916214059,12.507343278686905,
           -0.13857109526572012,9.9843695780195716e-6,1.5056327351493116e-7]
    if x<0.5: return math.log(math.pi)-math.log(math.sin(math.pi*x))-log_gamma(1-x)
    x-=1; a=c[0]; t=x+g+0.5
    for i in range(1,g+1):
        a+=c[i]/(x+i)
    return 0.5*math.log(2*math.pi)+(x+0.5)*math.log(t)-t+math.log(a)

def betacf(a,b,x,it=200):
    qab=a+b; qap=a+1; qam=a-1
    c=1; d=1-qab*x/qap
    if abs(d)<1e-30: d=1e-30
    d=1/d; h=d
    for m in range(1,it+1):
        m2=2*m
        aa=m*(b-m)*x/((qam+m2)*(a+m2))
        d=1+aa*d
        if abs(d)<1e-30: d=1e-30
        c=1+aa/c
        if abs(c)<1e-30: c=1e-30
        d=1/d; h*=d*c
        aa=-(a+m)*(qab+m)*x/((a+m2)*(qap+m2))
        d=1+aa*d
        if abs(d)<1e-30: d=1e-30
        c=1+aa/c
        if abs(c)<1e-30: c=1e-30
        d=1/d; delc=d*c; h*=delc
    return h

def ibeta(a,b,x):
    if x<=0: return 0.0
    if x>=1: return 1.0
    bt=math.exp(log_gamma(a+b)-log_gamma(a)-log_gamma(b)+a*math.log(x)+b*math.log(1-x))
    if x<(a+1)/(a+b+2):
        return bt*betacf(a,b,x)/a
    return 1-bt*betacf(b,a,1-x)/b

def clopper_pearson(k,n,alpha=0.05):
    if k==0: lo=0.0
    else: lo=ibeta(alpha/2,k,n-k+1)
    if k==n: hi=1.0
    else: hi=ibeta(1-alpha/2,k+1,n-k)
    return lo,hi

