# ---------- 2. Jonckheere-Terpstra statistic + permutation p-value (pure python)
def jt_stat(groups):
    U=0
    for i in range(len(groups)):
        for j in range(i+1,len(groups)):
            for a in groups[i]:
                for b in groups[j]:
                    U+=(1 if b>a else 0.5 if b==a else 0)
    return U

def jt_perm_p(groups,B=2000):
    obs=jt_stat(groups)
    allv=[v for g in groups for v in g]
    n=len(allv); lens=[len(g) for g in groups]; cnt=0
    for _ in range(B):
        random.shuffle(allv)
        idx=0; gs=[]
        for l in lens:
            gs.append(allv[idx:idx+l]); idx+=l
        if jt_stat(gs)>=obs: cnt+=1
    return (cnt+1)/(B+1)

