import itertools, math
Ls=[4,8,12,16,20,32,48,64,96,128]
# synthetic true curve: A=0.9, Bc=0.1, k=0.12 -> saturates around L~30
def true_asr(L): return 0.9-(0.9-0.1)*math.exp(-0.12*L)
def gen_data(seed,ns=12):
    rng=random.Random(seed); out=[]
    for L in Ls:
        p=min(0.999,max(0.001,true_asr(L)))
        out.append(sum(rng.random()<p for _ in range(ns))/ns)
    return out
